 int bg=Color.rgb(9,11,13),card=Color.rgb(23,27,30),card2=Color.rgb(31,36,39),muted=Color.rgb(148,156,164),green=Color.rgb(83,226,147),amber=Color.rgb(255,190,72),red=Color.rgb(255,99,99); LinearLayout root,content; String currentProject="Union Station Retrofit";
 int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} TextView t(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setIncludeFontPadding(false);return v;} GradientDrawable box(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;} void bold(TextView v){v.setTypeface(null,Typeface.BOLD);} void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
