 void base(String title,boolean back){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);pad(root,20,18,20,10);root.setBackgroundColor(bg);TextView h=t((back?"‹  ":"")+title,back?24:30,Color.WHITE);bold(h);h.setGravity(Gravity.CENTER_VERTICAL);h.setSingleLine(false);if(back)h.setOnClickListener(v->home());root.addView(h,new LinearLayout.LayoutParams(-1,-2));spaceRoot(18);ScrollView s=new ScrollView(this);s.setClipToPadding(false);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);s.addView(content);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);fade(root);}
