 void project(String n,String loc,String count,int pct){LinearLayout c=card();TextView x=t(n,22,Color.WHITE);bold(x);x.setMaxLines(2);c.addView(x);c.addView(t(loc+"  •  ACTIVE JOB",13,muted));spaceIn(c,16);ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(100);p.setProgressTintList(ColorStateList.valueOf(green));c.addView(p,new LinearLayout.LayoutParams(-1,dp(6)));animateProgress(p,pct);spaceIn(c,12);c.addView(t(count+"     "+pct+"% complete",15,Color.LTGRAY));press(c,()->{currentProject=n;projectScreen(n);});content.addView(c,new LinearLayout.LayoutParams(-1,-2));space(14);}
